:root {
  --ink: #08030f;
  --ink-2: #0e061a;
  --bone: #fff0d2;
  --muted: #b9a8c9;
  --pink: #ff3fae;
  --pink-hot: #ff77d3;
  --orange: #ff8a1e;
  --amber: #ffd23f;
  --cyan: #45f5ff;
  --violet: #9c5cff;
  --green: #7dff9a;
  --panel: rgba(16, 7, 27, 0.58);
  --panel-line: rgba(255, 209, 157, 0.18);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }

html, body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: var(--ink);
  color: var(--bone);
  font-family: 'Rajdhani', system-ui, sans-serif;
  -webkit-tap-highlight-color: transparent;
  -webkit-user-select: none;
  user-select: none;
  touch-action: none;
  overscroll-behavior: none;
}

body { position: fixed; inset: 0; }

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

#app, #stage, #stage canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

#stage canvas { display: block; }

.hidden {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

.screen-fx {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 5;
}

.vignette {
  box-shadow:
    inset 0 0 11vmin rgba(0, 0, 0, 0.72),
    inset 0 0 26vmax rgba(17, 2, 30, 0.34);
  background:
    linear-gradient(180deg, rgba(5, 1, 12, 0.35), transparent 22%, transparent 78%, rgba(5, 1, 12, 0.5));
}

.grain {
  opacity: 0.085;
  mix-blend-mode: soft-light;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.9'/%3E%3C/svg%3E");
  animation: grain-shift 0.7s steps(2) infinite;
}

@keyframes grain-shift {
  0% { transform: translate3d(0,0,0); }
  50% { transform: translate3d(-2%, 1%, 0); }
  100% { transform: translate3d(1%, -1%, 0); }
}

.scanlines {
  opacity: 0.14;
  background: repeating-linear-gradient(180deg, transparent 0 3px, rgba(0, 0, 0, 0.42) 3px 4px);
  mix-blend-mode: multiply;
}

/* ---------------- HUD ---------------- */

#hud {
  position: fixed;
  inset: 0;
  z-index: 12;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.hud-top {
  position: absolute;
  top: calc(14px + var(--safe-top));
  left: calc(16px + var(--safe-left));
  right: calc(16px + var(--safe-right));
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 12px;
}

.hud-left, .hud-right, .hud-center { display: flex; align-items: flex-start; }
.hud-right { justify-content: flex-end; gap: 8px; }
.hud-center { flex-direction: column; align-items: center; gap: 6px; }

.score-wrap {
  position: relative;
  min-width: 150px;
  padding: 9px 16px 8px 14px;
  background: linear-gradient(135deg, rgba(14, 5, 25, 0.78), rgba(14, 5, 25, 0.36));
  border-left: 2px solid var(--pink);
  clip-path: polygon(0 0, 100% 0, calc(100% - 12px) 100%, 0 100%);
  backdrop-filter: blur(8px);
}
.score-wrap::after {
  content: '';
  position: absolute;
  left: 0; bottom: 0; width: 54%; height: 1px;
  background: linear-gradient(90deg, var(--pink), transparent);
}
.hud-label {
  display: block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.22em;
  color: var(--pink-hot);
  text-shadow: 0 0 12px rgba(255, 63, 174, 0.6);
  line-height: 1;
}
.score-value {
  display: inline-block;
  font-weight: 700;
  font-size: clamp(30px, 4.8vw, 44px);
  line-height: 0.95;
  letter-spacing: 0.02em;
  color: #fff3da;
  text-shadow: 0 0 24px rgba(255, 138, 30, 0.2);
  font-variant-numeric: tabular-nums;
}
.distance-value {
  margin-left: 8px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

.candy-pill {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 96px;
  height: 42px;
  padding: 0 18px 0 12px;
  justify-content: center;
  background: rgba(14, 5, 25, 0.72);
  border: 1px solid rgba(255, 210, 63, 0.4);
  border-radius: 999px;
  box-shadow: 0 0 24px rgba(255, 157, 28, 0.16), inset 0 0 18px rgba(255, 157, 28, 0.08);
  backdrop-filter: blur(8px);
}
.candy-icon { width: 20px; height: 27px; filter: drop-shadow(0 0 7px rgba(255, 174, 38, 0.85)); }
#candy-count {
  font-size: 24px;
  font-weight: 700;
  line-height: 1;
  color: var(--amber);
  text-shadow: 0 0 15px rgba(255, 210, 63, 0.55);
  font-variant-numeric: tabular-nums;
}

.combo {
  display: flex;
  align-items: baseline;
  gap: 5px;
  padding: 3px 12px;
  border-radius: 3px;
  background: rgba(255, 63, 174, 0.16);
  border: 1px solid rgba(255, 63, 174, 0.55);
  color: #ffc4ec;
  box-shadow: 0 0 20px rgba(255, 63, 174, 0.32);
  transform: skewX(-8deg);
  transition: opacity 0.2s ease;
}
.combo span { font-size: 18px; font-weight: 700; }
.combo small { font-size: 8px; letter-spacing: 0.18em; font-weight: 700; opacity: 0.8; }

.icon-btn {
  pointer-events: auto;
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  color: #f5ddc6;
  background: rgba(14, 5, 25, 0.62);
  border: 1px solid rgba(255, 240, 210, 0.18);
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
  backdrop-filter: blur(8px);
  transition: color 0.2s, background 0.2s, transform 0.15s;
}
.icon-btn:hover { color: #fff; background: rgba(255, 63, 174, 0.18); transform: translateY(-1px); }
.icon-btn svg { width: 21px; height: 21px; }
.ico-muted { display: none; }
body.muted .ico-sound { display: none; }
body.muted .ico-muted { display: block; }
body.muted #btn-mute { color: #7b668f; }

.powerups {
  position: absolute;
  top: calc(82px + var(--safe-top));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 7px;
  pointer-events: none;
}
.power-chip {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 9px 5px 6px;
  background: rgba(10, 4, 19, 0.8);
  border: 1px solid currentColor;
  border-radius: 3px;
  box-shadow: 0 0 18px color-mix(in srgb, currentColor 40%, transparent);
  position: relative;
  overflow: hidden;
  animation: chip-in 0.25s ease;
}
@keyframes chip-in { from { opacity: 0; transform: translateY(-5px) scale(0.9); } }
.power-chip .dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 10px currentColor;
}
.power-chip span { font-size: 10px; font-weight: 700; letter-spacing: 0.1em; color: #fff; white-space: nowrap; }
.power-chip .bar {
  position: absolute; bottom: 0; left: 0; height: 2px; background: currentColor;
  box-shadow: 0 0 8px currentColor;
}

.toast {
  position: absolute;
  left: 50%;
  top: 25%;
  transform: translate(-50%, -8px);
  text-align: center;
  font-size: clamp(17px, 2.4vw, 23px);
  font-weight: 700;
  letter-spacing: 0.14em;
  color: #fff;
  text-shadow: 0 0 16px rgba(255, 63, 174, 0.7), 0 0 40px rgba(255, 63, 174, 0.35);
  opacity: 0;
  transition: opacity 0.22s ease, transform 0.22s ease;
  white-space: nowrap;
  pointer-events: none;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.toast small {
  display: block;
  font-size: 9px;
  letter-spacing: 0.3em;
  color: var(--muted);
  margin-top: 4px;
}

.tutorial {
  position: absolute;
  left: 50%;
  bottom: calc(26px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 7px;
  white-space: nowrap;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: rgba(255, 240, 210, 0.62);
  transition: opacity 0.8s ease;
}
.tutorial i { width: 2px; height: 2px; background: rgba(255,255,255,0.4); border-radius: 50%; margin: 0 2px; }
.tutorial-key {
  color: var(--cyan);
  border: 1px solid rgba(69, 245, 255, 0.35);
  padding: 3px 6px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  box-shadow: 0 0 12px rgba(69, 245, 255, 0.12) inset;
}

/* ---------------- Screens / menu ---------------- */

.screen {
  position: fixed;
  inset: 0;
  z-index: 30;
  transition: opacity 0.4s ease, visibility 0.4s;
}

.menu-screen {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: calc(28px + var(--safe-top)) calc(36px + var(--safe-right)) calc(24px + var(--safe-bottom)) calc(36px + var(--safe-left));
  background:
    radial-gradient(60% 90% at 72% 55%, rgba(55, 9, 66, 0.06) 0%, rgba(8, 2, 15, 0.3) 55%, rgba(6, 2, 12, 0.86) 100%),
    linear-gradient(90deg, rgba(6, 2, 12, 0.92) 0%, rgba(6, 2, 12, 0.62) 42%, rgba(6, 2, 12, 0.08) 72%, rgba(6, 2, 12, 0.46) 100%);
}
.menu-screen::after {
  content: '';
  position: absolute;
  inset: auto 0 0;
  height: 30%;
  background: linear-gradient(180deg, transparent, rgba(4, 1, 9, 0.75));
  pointer-events: none;
}
.menu-content {
  position: relative;
  z-index: 2;
  width: min(650px, 57vw);
  animation: menu-rise 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
@keyframes menu-rise {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: translateY(0); }
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.34em;
  color: rgba(255, 240, 210, 0.6);
  margin-bottom: 12px;
}
.pulse-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--orange);
  box-shadow: 0 0 14px var(--orange);
  animation: pulse 1.9s ease infinite;
}
@keyframes pulse { 0%,100% { opacity: 1; transform: scale(1); } 50% { opacity: .45; transform: scale(.72); } }

.game-title {
  margin: 0 0 16px;
  font-family: 'Creepster', fantasy;
  font-weight: 400;
  line-height: 0.76;
  letter-spacing: 0.005em;
  text-transform: uppercase;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  filter: drop-shadow(0 8px 30px rgba(0,0,0,0.65));
}
.title-neon {
  position: relative;
  font-size: clamp(76px, 11.6vw, 158px);
  color: #ffe8bd;
  -webkit-text-stroke: 1px rgba(255, 210, 63, 0.5);
  text-shadow:
    0 0 2px #fff2c9,
    0 0 12px rgba(255, 138, 30, 0.8),
    0 0 34px rgba(255, 98, 16, 0.5),
    0 4px 0 #7b2718,
    0 8px 0 #2b1117;
  transform: rotate(-2deg);
}
.title-hollow {
  margin-left: clamp(18px, 4vw, 58px);
  position: relative;
  font-size: clamp(76px, 11.6vw, 158px);
  color: #ffd9f2;
  -webkit-text-stroke: 1.5px rgba(255, 63, 174, 0.65);
  text-shadow:
    0 0 2px #fff,
    0 0 9px rgba(255, 63, 174, 1),
    0 0 26px rgba(255, 63, 174, 0.8),
    0 0 55px rgba(255, 31, 141, 0.5),
    0 5px 0 #440e45,
    0 9px 0 #18051f;
  transform: rotate(1.5deg);
