.tagline {
  margin: 0 0 25px;
  max-width: 465px;
  font-size: clamp(14px, 1.7vw, 18px);
  line-height: 1.5;
  font-weight: 500;
  color: #d9c8df;
  text-shadow: 0 2px 12px rgba(0,0,0,0.7);
}

.menu-actions { display: flex; align-items: center; gap: 18px; margin-bottom: 30px; }

.primary-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  height: 58px;
  padding: 0 30px;
