  }
  ui.tutorial.style.opacity = '';
  ui.tutorial.classList.remove('hidden');
  if (tutorialTimer) clearTimeout(tutorialTimer);
  tutorialTimer = setTimeout(() => {
    ui.tutorial.classList.add('hidden');
    tutorialTimer = null;
  }, 6500);
}

